:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #f9c74f;
  --secondary: #90be6d;
  --text: #f0f0f5;
  --shadow: rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 0 12px 32px var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 0.5px;
}

.points-display {
  font-size: 1.5rem;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.06);
  padding: 12px 20px;
  border-radius: 16px;
}

#points {
  color: var(--primary);
  font-size: 2rem;
  font-weight: 800;
}

.coin {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 6rem;
  line-height: 1;
  padding: 16px;
  border-radius: 50%;
  transition: transform 0.1s ease, filter 0.2s ease;
  align-self: center;
  width: 140px;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 8px 12px var(--shadow));
}

.coin:hover {
  filter: drop-shadow(0 8px 20px var(--primary));
  transform: scale(1.05);
}

.coin:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 4px;
}

.coin:active {
  transform: scale(0.92);
}

.coin.pressed {
  animation: press 0.15s ease;
}

@keyframes press {
  0% { transform: scale(1); }
  50% { transform: scale(0.85); }
  100% { transform: scale(1); }
}

.upgrade-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.upgrade-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 1.1rem;
}

#upgrade-count, #next-price {
  color: var(--secondary);
  font-weight: 700;
}

.buy-button {
  background: var(--primary);
  color: #1e1e2f;
  border: none;
  border-radius: 12px;
  padding: 14px 24px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease, opacity 0.2s ease;
  font-family: inherit;
}

.buy-button:hover:not(:disabled) {
  background: #f8b72e;
  transform: translateY(-2px);
}

.buy-button:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 2px;
}

.buy-button:active:not(:disabled) {
  transform: scale(0.97);
}

.buy-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.hint {
  font-size: 0.95rem;
  color: #aaa;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .coin {
    font-size: 4.5rem;
    width: 110px;
    height: 110px;
  }
  .points-display {
    font-size: 1.2rem;
  }
  #points {
    font-size: 1.6rem;
  }
}

let points = 0;
let upgradeCount = 0;
let nextPrice = 10;

const pointsEl = document.getElementById('points');
const upgradeCountEl = document.getElementById('upgrade-count');
const nextPriceEl = document.getElementById('next-price');
const coinBtn = document.getElementById('coin');
const buyBtn = document.getElementById('buy-upgrade');

function updateUI() {
  pointsEl.textContent = Math.floor(points);
  upgradeCountEl.textContent = upgradeCount;
  nextPriceEl.textContent = nextPrice;
  buyBtn.disabled = points < nextPrice;
}

function addPoints(amount) {
  points += amount;
  updateUI();
}

coinBtn.addEventListener('click', () => {
  addPoints(1);
  coinBtn.classList.remove('pressed');
  void coinBtn.offsetWidth; // trigger reflow to restart animation
  coinBtn.classList.add('pressed');
});

buyBtn.addEventListener('click', () => {
  if (points >= nextPrice) {
    points -= nextPrice;
    upgradeCount += 1;
    nextPrice *= 2;
    updateUI();
  }
});

setInterval(() => {
  if (upgradeCount > 0) {
    points += upgradeCount;
    updateUI();
  }
}, 1000);

updateUI();
